      solution: 'static int LängstaPlusserie(int[] tal)\n{\n    int nu = 0;\n    int bäst = 0;\n    foreach (int t in tal)\n    {\n        if (t > 0)\n        {\n            nu++;\n            if (nu > bäst)\n            {\n                bäst = nu;\n            }\n        }\n        else\n        {\n            nu = 0;\n        }\n    }\n    return bäst;\n}',
